mapper.update:
UPDATE mk_referral_qualification SET goal_type=#{q.goalType},state=#{q.state},reason=#{q.reason},counted=#{q.counted},ever_qualified=#{q.everQualified},
      qualification_revision=#{q.revision},evidence_resource_id=#{q.evidenceResourceId},evidence_state_version=#{q.evidenceVersion},member_revision=#{q.memberRevision},
      member_policy=#{q.memberPolicy},first_order_policy=#{q.firstOrderPolicy},proof_id=#{q.proofId},due_seconds=#{dueSeconds},due_nanos=#{dueNanos},task_revision=#{q.taskRevision},member_evidence_digest=#{q.memberEvidenceDigest},member_quarantined=#{q.memberQuarantined},registration_anchor_digest=#{q.registrationAnchorDigest},updated_at=#{now}
    WHERE tenant_id=#{q.tenantId} AND relation_id=#{q.relationId} AND participant_id=#{q.participantId} AND qualification_revision=#{previousRevision}
      AND policy_hash=#{q.policyHash} AND (goal_type IS NULL OR goal_type=#{q.goalType})

UPDATE mk_referral_evaluation_task SET processed_revision=#{requested},status=#{status},available_at=#{available},available_seconds=#{seconds},available_nanos=#{nanos},
      lease_owner=NULL,lease_until=NULL,row_version=row_version+1,updated_at=#{now}
    WHERE tenant_id=#{tenant} AND relation_id=#{relation} AND requested_revision=#{requested} AND fence=#{fence} AND status='PROCESSING' AND lease_owner=#{owner}
